// The device's check of an open proposal against the server's (OpenSpec change
// assistant-proposal-editing, task 1.3): open.vectors.json is generated by
// `go test ./internal/assistant -run DeviceOpenVectors -update` from
// Registry.OpenProposal over the same rows.
import 'fake-indexeddb/auto'
import { beforeEach, expect, it } from 'vitest'
import { AGENT_EXCLUSIONS_KEY } from '../agentAccess'
import type { ProposedChange } from '../assistantTypes'
import { db, setMeta, useDatabase } from '../db'
import { setCurrentUserId } from '../sharing'
import { loadSnapshot } from './data'
import { checkOpen } from './open'
import vectors from './open.vectors.json'

let n = 0
beforeEach(async () => {
  useDatabase(`device-open-${Date.now()}-${n++}`)
  await setCurrentUserId(vectors.user)
  const rows = vectors.rows as Record<string, Record<string, unknown>[]>
  await db.projects.bulkPut(rows.project.map((r) => ({ ...r, _clock: {} })) as never)
  await db.sections.bulkPut(rows.section.map((r) => ({ ...r, _clock: {} })) as never)
  await db.tasks.bulkPut(rows.task.map((r) => ({ ...r, _clock: {} })) as never)
  await db.notes.bulkPut(rows.note.map((r) => ({ ...r, _clock: {} })) as never)
  await db.places.bulkPut(rows.place.map((r) => ({ ...r, _clock: {} })) as never)
  await setMeta(AGENT_EXCLUSIONS_KEY, vectors.kept_away)
})

it('keeps the same items as the server', async () => {
  const kept = await checkOpen(vectors.open as unknown as ProposedChange[], await loadSnapshot())
  expect(kept.map((c) => `${c.entity}:${c.entityId}`)).toEqual(vectors.kept)
})
